<?php require 'inc/bootstrap.php';if(me())go('dashboard.php');
if($_SERVER['REQUEST_METHOD']==='POST'){chk();if(ipBlocked()){flash('Too many failed attempts from this device. Wait 15 minutes and try again.',1);go('login.php');}$un=strtolower(trim($_POST['u']??''));$u=q('SELECT * FROM users WHERE username=?',[$un])->fetch();
