 elseif($u&&$u['active']&&password_verify($_POST['p']??'',$u['pass_hash'])){q('UPDATE users SET fails=0,locked_until=NULL,last_login=NOW() WHERE id=?',[$u['id']]);session_regenerate_id(true);
  $_SESSION['u']=['id'=>$u['id'],'name'=>$u['name'],'role'=>$u['role'],'must_change'=>(int)$u['must_change']];$_SESSION['last']=time();audit('login');go('dashboard.php');}
 else{if($u)q('UPDATE users SET locked_until=IF(fails+1>=5,DATE_ADD(NOW(),INTERVAL 10 MINUTE),NULL),fails=IF(fails+1>=5,0,fails+1) WHERE id=?',[$u['id']]);ipFail();audit('login_failed',$un);flash('Wrong username or password, or the account is disabled.',1);}
 go('login.php');}
